def main():
    os.makedirs(blog_generator.DIR, exist_ok=True)
    existing = set()
    for f in os.listdir(blog_generator.DIR):
        if f.endswith('.mdx'):
            existing.add(f.replace('.mdx', ''))
    
    created = 0
    skipped = 0
    for title, slug, date, description, tags, category in TOPICS:
        if slug in existing:
            skipped += 1
            continue
        sections = generate_sections(title, slug, category, tags)
        ok = blog_generator.write_blog(title, slug, date, description, tags, category, sections)
        if ok:
            created += 1
            existing.add(slug)
    
    print(f"\n✅ Created {created} blogs, skipped {skipped} (already exist)")
    print(f"Total blogs now: {len(existing)}")


